import wollok.game.*
import config.crearMapa.creadorDeMapa //no se elimina porque el ancho y alto es del mapa
import src.paredes.*
object manejarCeldas {
  method obtenerCeldasDisponibles(){
        const celdasAncho = (0 .. creadorDeMapa.ancho() - 1)
        const celdasAlto  = (0 .. creadorDeMapa.alto() - 1)
        // Recorre todos los valores disponibles para las celdas en alto y en ancho, y genera una lista con todas las posibles celdas
        return celdasAncho.flatMap(
            { 
                x => celdasAlto.map(
                    { 
                        y => game.at(x, y) 
                    }
                ) 
            }
        )
    }
    method obtenerCeldasVacias() {
        return self.obtenerCeldasDisponibles().filter({
            celda => game.getObjectsIn(celda).isEmpty()
        })
    }
}

object manejarParedes {
        method crearPared(posicion){
        game.addVisual(new Pared(position = posicion))
    }

    // Metodo que recorre todos los valores verticales desde un origen creando paredes
    method paredVertical(origen, desde, hasta){
        (desde .. hasta).forEach({
            y => self.crearPared(game.at(origen, y))
        })
    }

    // Metodo que recorre todos los valores horizontales desde un origen creando paredes
    method paredHorizontal(origen, desde, hasta){
        (desde .. hasta).forEach({
            x => self.crearPared(game.at(x, origen))
        })
    }

    // Método que crea todos los bordes del mapa
    method crearBordes() {
        (0 .. creadorDeMapa.ancho()-1).forEach({x =>
            self.crearPared(game.at (x, 0))
            self.crearPared(game.at (x, creadorDeMapa.alto()-1))
            })
        (1 .. creadorDeMapa.ancho()-2).forEach({y => 
            self.crearPared(game.at (0, y))
            self.crearPared(game.at (creadorDeMapa.ancho()-1, y))
            })
    }

    // Método que crea unas paredes dentro del mapa
    method crearObstaculos() {
        self.paredHorizontal(8, 2, 10)
        self.paredHorizontal(16, 14, 22)
        self.paredVertical(16, 2, 10)
        self.paredVertical(8, 14, 22)
    }


    method crearZonaSegura(centro){
        self.crearAnillo(centro, 2).forEach({
            celda => game.addVisual(new ZonaSegura(position = celda))
        })
    }
    method crearAnillo(centro, radio){
        const columnas = (centro.x() - radio .. centro.x() + radio)
        const filas    = (centro.y() - radio .. centro.y() + radio)
        return columnas.flatMap({ x => filas.map({ y => game.at(x, y) }) }).filter({
            celda => (celda.x() - centro.x()).abs() == radio or (celda.y() - centro.y()).abs() == radio
        })
    }

}

