import wollok.game.*
import src.personaje.*
object definirPersonaje {
  method activarPacman(pacman) {
    game.addVisual(pacman)
    self.definirMovimiento(pacman)
    self.definirColiciones(pacman)
  }

  method definirMovimiento(pacman) {
    pacman.inicializarMovimiento()

	keyboard.d().onPressDo { pacman.direccion(1, 0) }
	keyboard.a().onPressDo { pacman.direccion(-1, 0)}
	keyboard.w().onPressDo { pacman.direccion(0, 1) }
	keyboard.s().onPressDo { pacman.direccion(0, -1)} // Estas cuatro modifican la direccion en la que se mueve el pacman    
  }

  method definirColiciones(pacman) {
    game.onCollideDo(pacman, {
        elemento => elemento.chocarCon(pacman)
        }
      )
}

}

