object gestionarPuntaje {
    var property puntosRestantes = []
    // Método que filtra solo celdas para puntos (para mejor rendimiento)
    method celdasParaPuntos(){
        return manejarCeldas.obtenerCeldasVacias().filter({
            // Solo usamos celdas impares
            celda => celda.x().odd() and celda.y().odd()
        })
    }

    // Método que reparte todos los puntos del mapa en las celdas
    method repartirPuntos(){
        self.celdasParaPuntos().forEach({ 
            celda => self.agregarPunto(celda)
        })
    }

    // Método que crea un punto y lo guarda en los puntos restantes
    method agregarPunto(celda){
        const punto = new Punto(valor = 10, position = celda, imagen = "punto.png")
        puntosRestantes.add(punto) 
        game.addVisual(punto)
    }

    // Método que elimina un punto del mapa y de los restantes
    method eliminarPunto(punto){
        puntosRestantes.remove(punto)
        // si se acaban todos los puntos, gana el juego
        if(puntosRestantes.isEmpty())
            pacman.ganar()
    }
}

