import personaje.pacman

class Fantasma {
  const property nombre
  var property position
  var property image
  const property esPasable = true
  var property estaCongelado = false //valor para ver si el power up frutaCongelado esta activo
  const property esPersonaje = false 
  const intervalo = 200 // valor de ms en estado normal del fantasma
  const movimiento = game.tick(intervalo, {self.mover(pacman)}, false)

  method chocarCon(personaje) {
    if (personaje.esMortal()){
      personaje.perder()
    }

  }

  // Métodos que definen el movimiento del fantasma
  method inicializarMovimiento(){
    movimiento.start()
  }

  method detenerMovimiento(){
    movimiento.stop()
  }

  method mover(pacman) { // pacman se usa adentro de sus override
    if(!estaCongelado)
      {const libres = self.posicionesLibres()
      if (!libres.isEmpty()) {
        position = self.elegirPosicion(libres, pacman) // cada tipo de fantasma decide a cual de las casillas libres ir
      }}
  }
  method elegirPosicion(libres, pacman)  //cada uno elige su movimiento
  method distanciaA(posicion, pacman) = posicion.distance(pacman.position())
  // distance: distancia en linea recta entre dos posiciones

  method posicionValida(posicion) = //que este dentro de los bordes del juego, y que sea pasable el objeto (osea no una pared)
  posicion.x() >= 0 && posicion.x() < game.width() && 
  posicion.y() >= 0 && posicion.y() < game.height() &&
  game.getObjectsIn(posicion).all({ objeto => objeto.esPasable() })

  method posicionesVecinas() = [self.position().up(1), self.position().down(1), self.position().right(1), self.position().left(1)]
  method posicionesLibres() = self.posicionesVecinas().filter({ posicion => self.posicionValida(posicion) })
  //de las 4 direcciones que puede ir, ver cuales son validas y se queda con esas para guardarla en la lista en la cual despues los fantasmas van a elegir una cualquiera para moverse.
    // estructuras como { o => o.image() } son como las funciones anonimas de funcional. "o" es la variable temporal; => es un "toma este elemento y hace esto", lo que sigue es la condicion, da true o false

 //manejo power-up fruta congelada
 // congelar un fantasma
  method congelar (tiempo) {
    estaCongelado = true
    game.schedule(tiempo, {estaCongelado = false})
  }


//congelar a todos los fantasmas
  /*method congelarFantasmas(tiempo) {
    listaFantasmas.forEach({fantasma => fantasma.congelar(tiempo)})
  }*/
}

//ESTO
class Aleatorio inherits Fantasma (image = "pinkGhost.png") {
    override method elegirPosicion(libres, pacman) = libres.anyOne()
}

class Aleja inherits Fantasma (image = "cyanGhost.png") {
    override method elegirPosicion(libres, pacman) = 
    libres.max({ posicion => self.distanciaA(posicion, pacman)})
    //closure, la "funcion anonima", es el criterio por el cual elige el min/max
    // max con closure: calcula la distancia a pacman de cada casilla libre y devuelve la casilla (no la distancia) con el valor mas grande, asi se aleja
}

class Persigue inherits Fantasma (image = "redGhost.png") {
    override method elegirPosicion(libres, pacman) = 
    libres.min({ posicion => self.distanciaA(posicion, pacman)})
    // min con closure: igual que max, pero devuelve la casilla con la distancia mas chica
}

