class Pared{
    var property position
    const property esPasable = false
    var property esZonaSegura = false 

    method image() = "pared.png"

    // Método que define el comportamiento ante el choque
    method chocarCon(personaje){
        if (personaje.esPersonaje() && !esZonaSegura) {
            personaje.frenar()
        } 
    }
}
 class ZonaSegura inherits Pared{

    override method image() = "zonaSegura.png"

    override method chocarCon (personaje) {
        esZonaSegura = true
        super(personaje)

    }
 }

import fantasmas.listaFantasmas
import carteles.*

object pacman {
  var property position = game.at(5, 5)
  var property puntos = 0
  var direccionX = 0
  var direccionY = 0
  const property esPasable = true
  var property esRapido = false //valor para ver si el power up frutaRapida esta activo
  var property esMortal = true //valor para ver si el power up frutaInmortal esta activo
  const intervalo = 200 // valor de ms en estado normal del pacman
  const movimiento = game.tick(intervalo, {self.moverse()}, false)
  const property esPersonaje = true

  method image() = "pacman.png"

  //Método que define la dirección de movimiento
  method direccion(x, y){
    direccionX = x
    direccionY = y
  }

  // Método que define el movimiento efectuado
  method moverse(){
      position = position.up(direccionY)
      position = position.right(direccionX)
  }

  // Métodos que definen el movimiento del pacman
  method inicializarMovimiento(){
    movimiento.start()
  }

  method detenerMovimiento(){
    movimiento.stop()
  }

  // Método que define el comportamiento al colisionar con una pared
  method frenar()  {
    position = game.at(
      position.x() - direccionX,
      position.y() - direccionY
    )
    self.direccion(0, 0)
  }


  // Acción al colisionar con "Frutas"
  method comerFrutas(cantidad){
    self.sumarPuntos(cantidad)
    game.say(self, "+" + cantidad + "!")
  }

  // Acción de sumar un puntaje
  method sumarPuntos(cantidad){
    puntos += cantidad
  }
////////////////
  //manejo power-up fruta rapida
  method esVeloz (tiempo){
    esRapido = true 
    movimiento.interval(intervalo / 2) // Reduzco el intervalo normal a la mitad, duplicando velocidad
    game.schedule(tiempo, {
      esRapido = false
      movimiento.interval(intervalo)
      })
  }

  // Método que indica que perdiste la partida
  method perder(){
    self.terminarJuego(cartelPerdiste)
  }

  // Método que indica que ganaste la partida
  method ganar(){
    self.terminarJuego(cartelGanaste)
  }

  // Método que se lanza al finalizar el juego
  method terminarJuego(cartel) {
    // Detener el movimiento
    self.detenerMovimiento()
    listaFantasmas.forEach({ fantasma => fantasma.detenerMovimiento() })
    // Modificar los visuales
    game.removeVisual(puntaje)
    cartel.mostrar()
    //Finalizar juego
    game.schedule(50, { game.stop() })

  }
  //manejo power-up fruta inmortal
  method esInmortal(tiempo) {
    esMortal = false
    game.schedule(tiempo, {esMortal = true})
  }

}

// Ojeto que representa un label con el puntaje del personaje
object puntaje {
  method position() = game.center()
  method text() = "Puntaje: " + pacman.puntos()
  method textColor() = "FFFFFFFF"
  const property esPasable = true

  // Método necesario para que el juego no rompa
  method chocarCon(personaje) {}
}

class Portal {
    const property position
    var property destino = null
    const property esPasable = false
    var salidaElegida = null //cada portal elige su propia salida.

    method image() = "portal.png"

    method vecinas() = [position.right(1), position.left(1), position.up(1), position.down(1)]
    method salidasLibres() = self.vecinas().filter({ pos => game.getObjectsIn(pos).isEmpty() }) // asi la salida no es en otro portal, pared o zona segura?
    method salida() {

        if(null == salidaElegida) {
            const libres = self.salidasLibres()
            if (!libres.isEmpty()) {
                salidaElegida = libres.anyOne()
            }
        }
        return salidaElegida
    }

    method chocarCon(personaje) {
        const posicionSalida = destino.salida() 
        if (null != posicionSalida) { //Si no hay ninguna libre (portal rodeado), salida() devuelve null, el portal no teletransporta.
            personaje.position(posicionSalida)
            personaje.direccion(0, 0) // tambien es una manera de evitar un bucle infinito de ida y vuelta entre portales
        }
    }
}

object portales {
    method crearPar(posA, posB) {
        const a = new Portal(position = posA)
        const b = new Portal(position = posB)
        a.destino(b)
        b.destino(a)
        game.addVisual(a)
        game.addVisual(b)
    }
}

